import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0013: Why Unknown Outcomes Are Never Blindly Retried","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md","filePath":"adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0013-why-unknown-outcomes-are-never-blindly-retried.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0013-why-unknown-outcomes-are-never-blindly-retried" tabindex="-1">ADR-0013: Why Unknown Outcomes Are Never Blindly Retried <a class="header-anchor" href="#adr-0013-why-unknown-outcomes-are-never-blindly-retried" aria-label="Permalink to “ADR-0013: Why Unknown Outcomes Are Never Blindly Retried”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: recovery-engine.md §6.6, ADR-0008</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The engine crashes (or is OOM-killed / times out) mid-recovery-action; the attempt&#39;s outcome stays NULL. The action <strong>may have taken effect</strong> (service restarted), may not have, or may be half-done. Retrying directly doubles side effects — the service is restarted twice, network changes are issued twice, state is corrupted when idempotency declarations are wrong.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><code>OutcomeUnknown</code> is a first-class state: crash recovery marks non-terminal runs outcome-unknown and <strong>stops automatic handling</strong>, re-entering the &quot;probe → diagnose&quot; path with the resource&#39;s current state as the sole truth; unknown-outcome runs never re-execute using old diagnoses (P0 acceptance: unknown-outcome runs must not blindly retry). A new action is only possible when a new diagnosis finds the fault again with a new plan.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Retry once directly</strong>: side effects double (see background); it also masks &quot;what actually happened in the last round.&quot;</li><li><strong>Mark failed and give up</strong>: pushes a self-healable fault to a human, violating the self-healing goal.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: side effects are bounded; the fact chain (what ran, result unknown, what the new diagnosis found) is complete and auditable. Cons: the recovery path has one extra diagnosis cycle; probe quality matters more (diagnosis must be based on current health).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li><code>resume_unfinished</code> + <code>RecoveryRunStatus::OutcomeUnknown</code> + the engine event <code>recovery.outcome_unknown</code> (same-name notification event) implement this together.</li><li>Idempotency declaration (<code>idempotent = true</code>) is an optimization, not an exemption: unknown results always re-diagnose.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};